CREATE TABLE schema_migration (version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE admin_user (user_id text PRIMARY KEY, email text NOT NULL, role text NOT NULL CHECK(role IN ('owner','editor')), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX single_active_owner ON admin_user(role) WHERE role='owner' AND active;
CREATE TABLE content (id text PRIMARY KEY, kind text NOT NULL CHECK(kind IN ('home','service','project','faq','article','settings')), draft jsonb NOT NULL, published jsonb, revision integer NOT NULL DEFAULT 1, published_revision integer, updated_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz, first_published_at timestamptz, archived boolean NOT NULL DEFAULT false);
CREATE UNIQUE INDEX published_slug_unique ON content(kind,(published->>'slug')) WHERE published IS NOT NULL AND NOT archived AND kind IN ('service','project','article');
CREATE TABLE content_version (id bigserial PRIMARY KEY, content_id text NOT NULL REFERENCES content(id), revision integer NOT NULL, body jsonb NOT NULL, actor text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(content_id,revision));
CREATE TABLE project_service (project_id text REFERENCES content(id) ON DELETE CASCADE, service_id text REFERENCES content(id), PRIMARY KEY(project_id,service_id));
CREATE TABLE faq_service (faq_id text REFERENCES content(id) ON DELETE CASCADE, service_id text REFERENCES content(id), PRIMARY KEY(faq_id,service_id));
CREATE TABLE publish_job (id text PRIMARY KEY, content_id text REFERENCES content(id), action text NOT NULL, status text NOT NULL CHECK(status IN ('running','succeeded','failed')), revision integer, error text, actor text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz);
CREATE TABLE audit_log (id bigserial PRIMARY KEY, actor text NOT NULL, action text NOT NULL, target text NOT NULL, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE support_policy_version (id text PRIMARY KEY, body jsonb NOT NULL, actor text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE client_project (id text PRIMARY KEY, name text NOT NULL, summary text NOT NULL, status text NOT NULL DEFAULT 'planning', policy_id text NOT NULL REFERENCES support_policy_version(id), policy_snapshot jsonb NOT NULL, revision_limit integer NOT NULL DEFAULT 5 CHECK(revision_limit>=0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE support_ticket (id text PRIMARY KEY, project_id text NOT NULL REFERENCES client_project(id), title text NOT NULL, description text NOT NULL, category text NOT NULL CHECK(category IN ('BUG','REVISION','CHANGE_REQUEST')), status text NOT NULL DEFAULT 'open', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE revision_round (id text PRIMARY KEY, project_id text NOT NULL REFERENCES client_project(id), ticket_id text NOT NULL REFERENCES support_ticket(id), event_key text NOT NULL UNIQUE, delta integer NOT NULL CHECK(delta IN (-1,1)), compensates_id text UNIQUE REFERENCES revision_round(id), reason text NOT NULL, actor text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX revision_ticket_ledger ON revision_round(ticket_id);
CREATE TABLE inquiry (id text PRIMARY KEY, idempotency_key text NOT NULL UNIQUE, body jsonb NOT NULL, status text NOT NULL DEFAULT 'new', notification_status text NOT NULL DEFAULT 'unconfigured', privacy_snapshot jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE inquiry_event (id text PRIMARY KEY, inquiry_id text NOT NULL REFERENCES inquiry(id) ON DELETE CASCADE, visibility text NOT NULL CHECK(visibility IN ('internal','customer')), body text NOT NULL, actor text NOT NULL, delivery_status text NOT NULL DEFAULT 'not_sent', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE media_asset (id text PRIMARY KEY, original_name text NOT NULL, mime text NOT NULL, bytes bytea NOT NULL, size integer NOT NULL, alt text NOT NULL DEFAULT '', visibility text NOT NULL CHECK(visibility IN ('public','private')), inquiry_id text REFERENCES inquiry(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE redirect_rule (path text PRIMARY KEY, destination text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE search_observation (id text PRIMARY KEY, body jsonb NOT NULL, actor text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE diagnostic_run (id text PRIMARY KEY, result jsonb NOT NULL, actor text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rate_bucket (key text PRIMARY KEY, window_start timestamptz NOT NULL, hits integer NOT NULL);
CREATE TABLE gateway_nonce (nonce text PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO schema_migration(version) VALUES ('001');
